"""Load shared Milestone 2 wallet data from any bot skill tools module."""

from __future__ import annotations

import importlib.util
from pathlib import Path
from typing import Any


def mile2_shared_dir() -> Path:
    """Return the lib/ directory co-located with wallet_data.py."""
    return Path(__file__).resolve().parent


def load_wallet_data() -> Any:
    path = mile2_shared_dir() / "wallet_data.py"
    spec = importlib.util.spec_from_file_location("mile2_wallet_data", path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Unable to load wallet data from {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module
